/* The supplied guide is the source of truth for the HBO universe. */
const baseRender=render, baseGraphMarkup=graphMarkup, baseShowEntity=showEntity, baseShowSearch=showSearch;
const got=universes.got;
got.nodes=GOT_REFERENCE.nodes.slice().sort((a,b)=>a.order-b.order);
got.edges=GOT_RELATIONS;
got.levels=['Season 1','Season 2','Season 3','Season 4','Season 5','Season 6','Season 7','All seasons'];
got.path=['jon','ned','arya','hound','brienne-of-tarth','jaime-lannister','tyrion','dany'];
got.discoverIds=['jon','lyanna-stark','rhaegar-targaryen'];
got.discovery='A secret that changes two great houses.';
got.discoveryText='Trace Jon’s true parentage through Lyanna Stark and Rhaegar Targaryen, with the reference’s television canon.';
got.nodes.find(n=>n.id==='family-jon-s-true-family').level=6;
let gotLevel=7, marvelLevel=level, directoryQuery='',directoryGroup='All groups',directoryPage=1,directoryType='All',graphFocus='jon',timelineSeason='All',referenceSection='All';
try{const v=Number(localStorage.getItem('loreverse-got-level')??7);if(v>=0&&v<=7)gotLevel=v}catch{}
const fullLore=()=>universe==='got'?level===7:level===3;
const safeDescription=n=>universe==='got'&&level<n.revealLevel?'This complete biography contains later-season outcomes. Select “All seasons” in viewing progress to read the supplied account.':n.description;
const gotTypes=['Character','Creature','Faction','Battle','Event'];
// Querying and graph traversal always operate on the same spoiler-filtered IDs.
visible=()=>data().nodes.filter(n=>n.level<=level);
edges=()=>{const ids=new Set(visible().map(n=>n.id));return data().edges.filter(e=>e[3]<=level&&ids.has(e[0])&&ids.has(e[1]))};
function inlineMarkdown(text){const pieces=[];const re=/\[([^\]]+)\]\((https?:\/\/(?:[^\s()]|\([^)]*\))*)\)/g;let pos=0,m;while((m=re.exec(text))){pieces.push(esc(text.slice(pos,m.index)));pieces.push(`<a href="${esc(m[2])}" target="_blank" rel="noopener noreferrer">${esc(m[1])} ↗</a>`);pos=re.lastIndex}pieces.push(esc(text.slice(pos)));return pieces.join('').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')}
function markdownBlock(text){let html='',table=false,list=false;const close=()=>{if(table){html+='</tbody></table></div>';table=false}if(list){html+='</ul>';list=false}};for(const line of text.split('\n')){if(line.startsWith('|')){if(!table){if(list){html+='</ul>';list=false}html+='<div class="reference-table"><table><tbody>';table=true}if(/^\|[\s:|-]+\|$/.test(line))continue;html+='<tr>'+line.trim().slice(1,-1).split('|').map(c=>`<td>${inlineMarkdown(c.trim())}</td>`).join('')+'</tr>';continue}if(line.startsWith('- ')){if(table){html+='</tbody></table></div>';table=false}if(!list){html+='<ul>';list=true}html+=`<li>${inlineMarkdown(line.slice(2))}</li>`;continue}close();if(line.startsWith('### '))html+=`<h3>${inlineMarkdown(line.slice(4))}</h3>`;else if(line.trim())html+=`<p>${inlineMarkdown(line)}</p>`}close();return html}
function sourceLinks(n){const unique=[...new Map((n.sources||[]).map(s=>[s.url,s])).values()];return `<p class="source">${esc(n.source)} · HBO television continuity</p><details class="sources"><summary>${unique.length?'Source links from the guide':'Reference attribution'}</summary><p>These links were supplied with the guide. Section-level links provide context when the entry has no individual citation.</p>${unique.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ↗</a>`).join('')}</details>`}
function referenceButtons(){return `<button data-view="Reference" class="outline">Read the reference ↗</button>`}
function refreshChrome(){const d=data();$('#universeName').textContent=d.full;$('.marvel-mini').textContent=universe==='got'?'G':'M';$('#crumb').textContent=d.name;$('#saveCount').textContent=saved.length;$('#spoilerLabel').textContent=fullLore()?'All lore visible':d.levels[level];$$('nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$$('[data-got-only]').forEach(b=>b.hidden=universe!=='got');$('#universeSwitcher').setAttribute('aria-label','Choose universe: '+d.full);$('footer span:last-child').textContent=universe==='got'?'HBO series · Complete supplied reference':'Curated demo · MCU continuity'}
function resetDirectory(){directoryQuery='';directoryGroup='All groups';directoryPage=1;directoryType='All';timelineSeason='All'}
function directoryNodes(){return visible().filter(n=>view==='Characters'?n.type==='Character':view==='Creatures'?n.type==='Creature':view==='Battles'?n.type==='Battle':view==='Events'?n.type==='Event':view==='Factions'?n.type==='Faction':saved.includes(universe+':'+n.id))}
function searchable(n){return [n.name,n.subtitle,n.group,...(fullLore()?[n.referenceName||'',n.description]:[])].join(' ').toLowerCase()}
function directoryResults(){const q=directoryQuery.toLowerCase().trim();return directoryNodes().filter(n=>(directoryGroup==='All groups'||n.group===directoryGroup)&&(directoryType==='All'||n.type===directoryType)&&(!q||searchable(n).includes(q)))}
function directoryResultMarkup(){const ns=directoryResults(),pageCount=Math.max(1,Math.ceil(ns.length/24));directoryPage=Math.min(directoryPage,pageCount);const page=ns.slice((directoryPage-1)*24,directoryPage*24);return `<div class="directory-summary"><span>${ns.length} ${view==='Characters'?'character entries':'entries'}${view==='Characters'?' · Principal characters first':''}</span><span>Page ${directoryPage} of ${pageCount}</span></div>${page.length?`<div class="cards grid-all">${page.map(card).join('')}</div>`:'<div class="empty"><h2>No matching entries.</h2><p>Try another search, group, or viewing-progress setting.</p></div>'}<div class="pagination"><button class="outline" id="previousPage" ${directoryPage===1?'disabled':''}>← Previous</button><span>${directoryPage} / ${pageCount}</span><button class="outline" id="nextPage" ${directoryPage===pageCount?'disabled':''}>Next →</button></div>`}
function bindDirectory(){const update=()=>{$('#directoryResults').innerHTML=directoryResultMarkup();bindDirectoryResults()};$('#directorySearch').oninput=e=>{directoryQuery=e.target.value;directoryPage=1;update()};$('#directoryGroup').onchange=e=>{directoryGroup=e.target.value;directoryPage=1;update()};bindDirectoryResults()}
function bindDirectoryResults(){$$('#directoryResults [data-entity]').forEach(b=>b.onclick=()=>showEntity(b.dataset.entity));$('#previousPage').onclick=()=>{directoryPage--;$('#directoryResults').innerHTML=directoryResultMarkup();bindDirectoryResults();$('#directoryResults').scrollIntoView({block:'start'})};$('#nextPage').onclick=()=>{directoryPage++;$('#directoryResults').innerHTML=directoryResultMarkup();bindDirectoryResults();$('#directoryResults').scrollIntoView({block:'start'})}}
function renderDirectory(){const config={Characters:['The people behind the power.','The principal characters come first, followed by every supporting and minor entry in your guide.'],Creatures:['Dragons, direwolves, and companions.','Ten animals from the reference, with their complete television accounts.'],Battles:['The battles that shaped the realm.','Campaigns, sieges, rescues, and military turning points, including reported and off-screen action.'],Events:['Moments that changed everything.','Season overviews, major killings and duels, and the final settlement.'],Factions:['Bloodlines and allegiances.','Family relationships and collective entries from the supplied reference.'],Bookmarks:['Your saved lore.','A collection saved on this device. Your viewing progress still applies.']};const [heading,sub]=config[view];const groups=[...new Set(directoryNodes().map(n=>n.group))];return title(heading,sub,referenceButtons())+`<div class="directory-toolbar"><label>Search this collection<input id="directorySearch" value="${esc(directoryQuery)}" placeholder="Search names${fullLore()?', relationships, or story details':''}…"></label><label>Reference group<select id="directoryGroup"><option>All groups</option>${groups.map(g=>`<option ${directoryGroup===g?'selected':''}>${esc(g)}</option>`).join('')}</select></label></div>${!fullLore()?'<div class="note">Names and available connections follow your progress. Complete biographies and family summaries remain protected until All seasons.</div>':''}<div id="directoryResults">${directoryResultMarkup()}</div>`}
function gotGraph(large){const available=visible(),allEdges=edges();let ns;
 if(!large)ns=available.filter(n=>['jon','dany','tyrion','arya','ned','sansa-stark','jaime-lannister','cersei-lannister'].includes(n.id));
 else {if(!available.some(n=>n.id===graphFocus))graphFocus=available[0]?.id;const near=new Set([graphFocus]);allEdges.forEach(e=>{if(e[0]===graphFocus)near.add(e[1]);if(e[1]===graphFocus)near.add(e[0])});ns=available.filter(n=>near.has(n.id)&&(filter==='All'||n.type===filter||n.id===graphFocus));}
 const total=ns.length;ns=ns.slice(0,24);const positions={},height=large?510:290,cx=350,cy=height/2;
 const center=large?ns.find(n=>n.id===graphFocus):null;const ring=ns.filter(n=>n!==center);if(center)positions[center.id]={x:cx,y:cy};ring.forEach((n,i)=>{const a=i/ring.length*2*Math.PI-Math.PI/2;positions[n.id]={x:cx+Math.cos(a)*(large?265:210),y:cy+Math.sin(a)*(large?190:95)}});
 const es=allEdges.filter(e=>positions[e[0]]&&positions[e[1]]);return `<div class="graph-wrap ${large?'large':''}"><svg viewBox="0 0 700 ${height}" aria-label="Interactive Game of Thrones relationship graph"><g id="graphTransform">${es.map(e=>{const a=positions[e[0]],b=positions[e[1]];return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#70587f" opacity=".55"/><title>${esc(entity(e[0]).name+' '+e[2]+' '+entity(e[1]).name)}</title>`}).join('')}${ns.map(n=>{const p=positions[n.id],selected=n.id===graphFocus&&large;return `<g class="graph-node" role="button" tabindex="0" data-entity="${n.id}" aria-label="Explore ${esc(n.name)}" transform="translate(${p.x},${p.y})"><circle r="${selected?30:21}" fill="${selected?'#513463':'#262030'}" stroke="${palettes[n.color][1]}"/><text text-anchor="middle" y="7" font-size="24" fill="${palettes[n.color][1]}">${n.sigil}</text><text text-anchor="middle" y="${selected?46:36}" font-size="10" fill="#ddd0e8" paint-order="stroke" stroke="#17131e" stroke-width="4">${esc(n.name)}</text></g>`}).join('')}</g></svg><div class="graph-controls"><button id="zoomOut" aria-label="Zoom out">−</button><button id="resetGraph" aria-label="Reset graph">⊙</button><button id="zoomIn" aria-label="Zoom in">+</button></div></div><div class="legend"><span>${ns.length} visible nodes${total>24?` of ${total} nearby entities`:''}</span><span>Click a node to read its labeled relationships</span></div>`}
graphMarkup=large=>universe==='got'?gotGraph(large):baseGraphMarkup(large);
render=()=>{refreshChrome();if(universe!=='got'){baseRender();refreshChrome();return}let html='';
 if(view==='Explore'){
 const chars=visible().filter(n=>n.type==='Character').slice(0,8),count=t=>visible().filter(n=>n.type===t).length;
 html=title('Welcome to the Seven Kingdoms.','Every house has a history. Every choice changes the realm.',`<button class="outline" id="connectOpen">⌘ &nbsp; Connect two entities</button>`)+`<section class="hero got-hero"><div class="hero-content"><div class="eyebrow"><span class="badge got-badge">GOT</span>THE WORLD OF ICE AND FIRE</div><h2>A thousand stories.<br>One fight for the throne.</h2><p>Explore the complete reference—from the great houses to the people, creatures, and battles that shaped their world.</p><button class="primary" data-view="Characters">Meet the characters ↗</button><button class="outline" data-view="Lore Graph">Explore the graph</button></div><span class="hero-stamp">HBO SERIES · SEASONS 1–8</span></section><div class="stats"><span><b>${count('Character')}</b> Character entries</span><span><b>${count('Battle')}</b> Battles</span><span><b>${count('Creature')}</b> Creatures</span><span><b>${edges().length}</b> Relationships</span></div><div class="section-heading"><div><h2>The faces of the Seven Kingdoms</h2><p>The most familiar characters first. Every story is yours to explore.</p></div><button class="text-link" data-view="Characters">All characters ↗</button></div><div class="cards featured-got">${chars.map(card).join('')}</div><div class="reference-callout"><div><span class="eyebrow">YOUR COMPLETE REFERENCE</span><h3>Beyond the main cast.</h3><p>${got.nodes.length} entries across 15 sections. Supporting roles, family histories, season summaries, and unresolved fates—all preserved from your guide.</p></div>${referenceButtons()}</div><div class="lower"><div><div class="section-heading"><h2>Family, loyalty, and betrayal</h2><button class="text-link" data-view="Lore Graph">Open graph ↗</button></div><section class="graph-panel">${graphMarkup(false)}</section></div><div><div class="section-heading"><h2>Follow the story through time</h2></div><section class="discovery"><span class="eyebrow">EIGHT SEASONS. A CHANGING WORLD.</span><h3>From a royal visit to a new order.</h3><p>Browse the season-by-season story, then explore the battles and decisions that changed its course.</p><div class="actions"><button class="primary" data-view="Timeline">Explore timeline ↗</button><button class="outline" data-view="Battles">See battles ↗</button></div></section></div></div>`;
 }else if(['Characters','Creatures','Events','Battles','Factions','Bookmarks'].includes(view)){html=renderDirectory();}
 else if(view==='Lore Graph'){html=title('Follow the ties that bind.','Explore one entity and its immediate relationships. Drag to pan; use + and − to zoom.',`<button class="outline" id="connectOpen">⌘ Connect two entities</button>`)+`<div class="directory-toolbar"><label>Center the graph on<select id="graphFocus">${visible().map(n=>`<option value="${n.id}" ${n.id===graphFocus?'selected':''}>${esc(n.name)}</option>`).join('')}</select></label></div><div class="view-tabs">${['All',...gotTypes].map(t=>`<button data-filter="${t}" class="${filter===t?'active':''}">${t==='All'?'All relationships':t+'s'}</button>`).join('')}</div><section class="graph-panel">${graphMarkup(true)}</section><div class="note">${edges().length} explicit relationships in the available graph. Entries without a curated relationship remain available through profiles and search; no connection is invented from a passing mention.</div>`}
 else if(view==='Timeline'){const ns=visible().filter(n=>['Event','Battle'].includes(n.type)&&(timelineSeason==='All'||n.year===Number(timelineSeason))).sort((a,b)=>a.year-b.year||(a.episode||0)-(b.episode||0)||a.order-b.order);html=title('The realm, season by season.','Episode order follows your reference. Backstory is distinguished from events shown in the main series.')+`<div class="view-tabs">${['All',0,1,2,3,4,5,6,7,8].filter(x=>x==='All'||x===0&&fullLore()||x>0&&x<=level+1).map(s=>`<button data-season="${s}" class="${String(s)===String(timelineSeason)?'active':''}">${s==='All'?'All events':s===0?'Backstory':'Season '+s}</button>`).join('')}</div><div class="timeline">${ns.map(n=>`<button class="timeline-item" data-entity="${n.id}"><span class="eyebrow">${n.year?'SEASON '+n.year:'BEFORE SEASON 1'} · ${n.type}</span><h3>${esc(n.name)}</h3><p>${esc(n.subtitle)}</p></button>`).join('')}</div>`}
 else if(view==='Reference'){html=title('The complete reference.','All 15 sections of your supplied guide, including citations, canon notes, and unresolved outcomes.')+(fullLore()?`<div class="directory-toolbar"><label>Jump to a section<select id="referenceSection"><option>All</option>${GOT_REFERENCE.sections.map(s=>`<option value="${s.number}" ${String(s.number)===String(referenceSection)?'selected':''}>${s.number}. ${esc(s.title)}</option>`).join('')}</select></label><a class="outline download-guide" href="game-of-thrones-reference.md" download>Download original guide ↓</a></div><article class="reference-article"><div class="note">Full spoilers · HBO television canon. Grouped roles remain grouped; unknown fates are not invented.</div>${referenceSection==='All'?markdownBlock(GOT_REFERENCE.raw.split('\n## ')[0].split('\n').slice(1).join('\n')):''}${GOT_REFERENCE.sections.filter(s=>referenceSection==='All'||s.number===Number(referenceSection)).map(s=>`<section><h2>${s.number}. ${esc(s.title)}</h2>${markdownBlock(s.body)}</section>`).join('')}</article>`:'<div class="empty"><h2>The complete guide contains full-series spoilers.</h2><p>Select “All seasons” in viewing progress to read every section.</p><button class="primary" id="referenceProgress">Change viewing progress</button></div>')}
 else if(view==='Lore Paths'){html=title('A path through the Seven Kingdoms.','Follow a sequence of explicit relationships from Jon’s household to Daenerys’s advisers.')+`<section class="discovery"><span class="eyebrow">GUIDED EXPLORATION</span><h3>From the North to the dragon queen</h3>${got.path.filter(id=>visible().some(n=>n.id===id)).map((id,i)=>`<div class="path-step"><span>0${i+1}</span><button data-entity="${id}">${esc(entity(id).name)}<small>${esc(entity(id).subtitle)}</small></button></div>`).join('')}</section>`}
 $('#main').innerHTML=html;wire();if($('#directorySearch'))bindDirectory();if($('#graphFocus'))$('#graphFocus').onchange=e=>{graphFocus=e.target.value;zoom=1;pan={x:0,y:0};render()};$$('[data-season]').forEach(b=>b.onclick=()=>{timelineSeason=b.dataset.season;render()});if($('#referenceSection'))$('#referenceSection').onchange=e=>{referenceSection=e.target.value;render()};if($('#referenceProgress'))$('#referenceProgress').onclick=()=>$('#spoilerOpen').click();refreshChrome();
};
showEntity=id=>{if(universe!=='got')return baseShowEntity(id);const n=entity(id);if(!n||n.level>level)return;history.push(id);const related=edges().filter(e=>e[0]===id||e[1]===id),unlocked=level>=n.revealLevel;openModal(`${art(n)}<span class="eyebrow">${n.type} · HBO TELEVISION CANON</span><h2>${esc(n.name)}</h2><p>${esc(n.subtitle)}</p>${n.grouped?'<div class="note">Grouped reference entry: the guide describes these roles together.</div>':''}<div class="actions"><button class="primary" id="saveEntity">${saved.includes('got:'+id)?'✓ Saved lore':'＋ Save lore'}</button><button class="outline" id="entityGraph">Explore connections ↗</button></div>${unlocked&&n.referenceName!==n.name&&n.referenceName?`<p class="source">Reference name: ${esc(n.referenceName)}</p>`:''}<div class="biography">${unlocked?markdownBlock(n.description):`<div class="note">${safeDescription(n)}</div>`}</div>${unlocked?sourceLinks(n):''}<h3>Connected stories <span style="color:#a990bd">${related.length}</span></h3>${related.map(e=>{const other=entity(e[0]===id?e[1]:e[0]);return `<button class="result" data-entity="${other.id}"><b>${esc(other.name)}</b><span>${esc(entity(e[0]).name)} → ${esc(e[2])} → ${esc(entity(e[1]).name)}</span></button>`}).join('')||'<p>No curated relationships for this entry at your current viewing progress. Its supplied biography remains available above.</p>'}<p class="source">${history.length} stories explored this session · ${esc(n.group)}</p>`);$('#saveEntity').onclick=()=>{const key='got:'+id;saved=saved.includes(key)?saved.filter(x=>x!==key):[...saved,key];persist();$('#saveEntity').textContent=saved.includes(key)?'✓ Saved lore':'＋ Save lore';$('#saveCount').textContent=saved.length;if(view==='Bookmarks')render()};$('#entityGraph').onclick=()=>{graphFocus=id;filter='All';zoom=1;pan={x:0,y:0};$('#modal').close();view='Lore Graph';render()}};
showSearch=()=>{if(universe!=='got')return baseShowSearch();openModal(`<span class="eyebrow">SEARCH THE SEVEN KINGDOMS</span><h2>Find a thread to follow.</h2><input id="search" aria-label="Search lore" placeholder="A character, battle, family, or story…" autocomplete="off"><p class="source">${fullLore()?'Search every supplied name, alias, and biography.':'Only spoiler-safe names and available entries are searched.'} Principal characters rank first among equal matches.</p><div id="results" class="results"></div>`);const run=()=>{const q=$('#search').value.toLowerCase().trim();const ns=visible().map(n=>({n,score:!q?1:n.name.toLowerCase()===q?100:n.name.toLowerCase().includes(q)?20:searchable(n).includes(q)?5:0})).filter(x=>x.score).sort((a,b)=>b.score-a.score||a.n.order-b.n.order);$('#results').innerHTML=`<p class="source">${ns.length} matches${ns.length>30?' · Showing first 30; refine your search':''}</p>`+(ns.length?ns.slice(0,30).map(({n})=>`<button class="result" data-entity="${n.id}"><b>${esc(n.name)}</b><span>${n.type} ↗</span></button>`).join(''):'<p>No results at this viewing progress.</p>');wireModal()};$('#search').oninput=run;run();$('#search').focus()};
const oldGo=go;go=v=>{resetDirectory();oldGo(v)};
// Keep progress separate: switching worlds must not silently reveal another world's spoilers.
function switchUniverse(key){if(universe==='got')gotLevel=level;else marvelLevel=level;universe=key;level=key==='got'?gotLevel:marvelLevel;history=[];$('#modal').close();go('Explore')}
$('#universeSwitcher').onclick=()=>{openModal(`<span class="eyebrow">CHOOSE YOUR NEXT WORLD</span><h2>Enter the lore.</h2>${Object.entries(universes).map(([key,d])=>`<button class="universe-option" data-universe="${key}"><strong>${d.full} ↗</strong><span>${d.nodes.length} entries · ${key==='got'?'Complete supplied HBO reference':'Curated MCU sample'}</span></button>`).join('')}`);$$('[data-universe]').forEach(b=>b.onclick=()=>switchUniverse(b.dataset.universe))};
$('#spoilerOpen').onclick=()=>{openModal(`<span class="eyebrow">YOUR STORY. YOUR PROGRESS.</span><h2>Explore at your own pace.</h2><p>${universe==='got'?'Events and relationships follow season cutoffs. Complete reference biographies contain later outcomes and are shown only at All seasons.':'Choose your viewing milestone.'}</p><label for="progress" style="display:block;margin:22px 0 8px">I have watched up to</label><select id="progress">${data().levels.map((l,i)=>`<option value="${i}" ${i===level?'selected':''}>${l}</option>`).join('')}</select><div class="actions"><button class="primary" id="applyProgress">Save viewing progress</button></div>`);$('#applyProgress').onclick=()=>{level=Number($('#progress').value);try{if(universe==='got'){gotLevel=level;localStorage.setItem('loreverse-got-level',level)}else{marvelLevel=level;localStorage.setItem('loreverse-level',level)}}catch{notify('Progress saved for this session only.')}$('#modal').close();resetDirectory();render();notify('Viewing progress updated')}};
persist=()=>{try{localStorage.setItem('loreverse-saved',JSON.stringify(saved));localStorage.setItem(universe==='got'?'loreverse-got-level':'loreverse-level',level)}catch{notify('Storage unavailable. Changes last for this session.')}};
$('#searchOpen').onclick=()=>showSearch();
const nav=$('nav');[['Battles','⚔'],['Creatures','♞'],['Reference','▤']].forEach(([name,icon])=>{const b=document.createElement('button');b.dataset.view=name;b.dataset.gotOnly='';b.innerHTML=`<i>${icon}</i>${name==='Reference'?'Reference guide':name}`;b.onclick=()=>go(name);nav.appendChild(b)});
// Lead with the expanded universe on this release.
universe='got';level=gotLevel;render();
